async function fetchUserStoriesBySprint(sprint, areaPath, checkLinks = true) {
  // WIQL is ADO's SQL-ish work-item query language, POSTed to the /wiql endpoint
  const wiql = {
    query: `
      SELECT [System.Id] FROM WorkItems
      WHERE [System.WorkItemType] = 'User Story'
        AND [System.IterationPath] UNDER 'MyProject\\${sprint}'
        ${areaPath ? `AND [System.AreaPath] UNDER '${areaPath}'` : ''}
      ORDER BY [System.Id]
    `,
  };
  const queryResult = await fetchFromADO('/wit/wiql?api-version=7.0', 'POST', wiql);
  const workItemIds = (queryResult.workItems || []).map(wi => wi.id); // WIQL returns IDs only (a reference list), never field data — hence the hydrate step next

  // Hydrate in batches of 200 — ADO's work-items batch endpoint caps at 200 IDs per call, so larger
  // sprints must be chunked. Each item's HTML fields are stripped to text, the acceptance criteria is
  // content-hashed (for later drift detection), and if checkLinks, existing 'TestedBy' test cases are fetched.
  return stories;
}

async function fetchLinkedTestCases(workItemId) {
  // $expand=relations is required — without it the work item comes back with no link data at all
  const result = await fetchFromADO(
    `/wit/workitems/${workItemId}?api-version=7.0&$expand=relations`
  );
  const testCases = [];
  for (const rel of result.relations || []) {
    if (rel.rel === 'Microsoft.VSTS.Common.TestedBy-Forward') { // only the story->test 'TestedBy' forward link; ignores parents, children, other relation types
      const testCaseId = parseInt(rel.url.split('/').pop()); // relations carry only a URL, so the numeric ID is parsed off the tail of the path
      const tc = await fetchFromADO(`/wit/workitems/${testCaseId}?api-version=7.0`);
      testCases.push({
        id: tc.id,
        title: tc.fields['System.Title'],
        state: tc.fields['System.State'],
        automationStatus: tc.fields['Microsoft.VSTS.TCM.AutomationStatus'] || 'Not Automated', // field is absent on manual tests, so default it rather than leaving undefined
      });
    }
  }
  return testCases;
}

async function generateTestCasesWithLLM(story, intel, contextDocs, mode, outputFormat) {
  let context = `STORY: US-${story.id} — ${story.title}\n`;
  context += `ACCEPTANCE CRITERIA:\n${story.acceptanceCriteria}\n`;
  if (intel) { // intel is the prior Test-Scout briefing; when present it enriches the prompt with rules + edge cases
    context += `\nBUSINESS RULES:\n${intel.businessRules.map(r => `- ${r.name}: ${r.description}`).join('\n')}\n`;
    context += `\nEDGE CASES:\n${intel.edgeCases.map(e => `- [${e.priority}] ${e.scenario}`).join('\n')}\n`;
  }

  const prompt = `You are a senior QA engineer generating detailed,
executable test cases.
${context}
Generate test cases for each acceptance criterion,
with concrete steps and expected results. Respond as a JSON array.`;

  const response = await callGeminiFlash(prompt, { temperature: 0.3, maxTokens: 8192 }); // temp 0.3: low, so cases stay concrete/repeatable rather than creative; 8k out for a full suite
  const llmCases = parseLLMJson(response.answer); // tolerant JSON parse — strips fences the model may wrap the array in
  return llmCases.map((tc, index) => buildBlueprint(story, tc, index, intel, mode, outputFormat)); // each raw case -> a blueprint carrying the source hash + mode (plain / Given-When-Then)
}

function analyzeForUIDetails(title, description, ac, workItemType) {
  const combinedText = `${title} ${description} ${ac}`.toLowerCase();
  const missingElements = [];

  if (description.length < 50) missingElements.push('Missing/short description'); // <50 chars = effectively no description; a real spec is longer
  if (ac.length < 30 && workItemType !== 'Bug') missingElements.push('Missing acceptance criteria'); // bugs are exempt — they legitimately have no AC, so don't flag them

  // A testable UI story should reference a design somewhere; none of these keywords => no design link
  if (!combinedText.includes('figma') && !combinedText.includes('design') &&
      !combinedText.includes('wireframe') && !combinedText.includes('mockup')) {
    missingElements.push('No design reference (Figma/wireframe)');
  }
  if (title.toLowerCase().includes('qa test') && description.length < 30 && ac.length < 30) {
    missingElements.push('QA Test task has no test case details');
  }

  const hasUIDetails = missingElements.length < 2; // tolerate ONE gap: 2+ missing elements means the story is too thin to test
  return { hasUIDetails, missingElements };
}

function detectContentChanges(story, existingBlueprints) {
  const storyBlueprints = Array.from(existingBlueprints.values())
    .filter(bp => bp.source.workItemId === story.id);
  if (storyBlueprints.length === 0) return null; // no prior draft for this story => nothing to compare, so no drift to report

  const latest = storyBlueprints[0];
  // Compare stored vs live AC content hash — a cheap exact-equality test, no diffing needed
  if (latest.source.acceptanceCriteriaHash === story.acceptanceCriteriaHash) {
    return null; // no changes
  }

  // Drift confirmed. If any linked test is still in 'Design' (not yet executed) it's safe to auto-update;
  // otherwise recommend a human review before touching tests that may already have run
  const recommendAction = story.linkedTestCases.some(tc => tc.state === 'Design')
    ? 'update_tests'
    : 'review_tests';

  return {
    storyId: story.id, storyTitle: story.title,
    previousHash: latest.source.acceptanceCriteriaHash,
    currentHash: story.acceptanceCriteriaHash,
    recommendAction, linkedTestCases: story.linkedTestCases,
  };
}

function generateFeatureReportMarkdown(report) {
  // Whole report is one Markdown template literal; ${...} blocks interpolate live data inline.
  // Coverage % = storiesWithTests / totalUserStories (Math.round to a whole number); the per-row
  // checkmark flags whether that story has any linked test; the gap section lists only thin stories.
  return `# Feature Test Coverage & Gap Analysis Report
**Feature:** ${report.feature.title} (ID: ${report.feature.id})
**Test Coverage:** ${Math.round(
    (report.summary.storiesWithTests / report.summary.totalUserStories) * 100
  )}%

## Test Coverage by User Story
| Story ID | Title | State | Test Cases | Coverage |
${report.testCoverage.map(tc =>
  `| US-${tc.storyId} | ${tc.storyTitle} | ${tc.state} | ${tc.linkedTestCases.length} | ${tc.hasTests ? '✅' : '❌'} |`
).join('\n')}

## Gap Analysis — Items Needing Developer Input
${report.gapAnalysis.map(gap => `### US-${gap.storyId}: ${gap.storyTitle}`).join('\n')}
`;
}
